Diseño responsive.ejemplo:
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 18rem), 1fr));
  gap: clamp(1rem, 2vw, 2rem);
}
@container (min-width: 400px) {
  .card { flex-direction: row; }
}

