Microinteracciones.ejemplo:
.toast {
  transition: transform 200ms cubic-bezier(0.2, 0, 0, 1), opacity 200ms ease-out;
}
@media (prefers-reduced-motion: reduce) {
  .toast { transition: opacity 100ms linear; transform: none; }
}

